import{_ as a,c as p,a as n,o as r}from"./app-CxQdQpt9.js";const c={};function d(i,e){return r(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-18-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-18-资讯日报"><span>2026-11-18 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="_63家ai硬件公司融资数降44" tabindex="-1"><a class="header-anchor" href="#_63家ai硬件公司融资数降44"><span>63家AI硬件公司融资数降44%</span></a></h3><p>统计显示，获融资企业从2025年的27家降至2026年11月11日的15家，减少44%；资本转向有真实销量和持续使用数据的产品。</p><p>商业化：明确解决需求的垂类产品领先</p><p>订阅：Oura会员收入同比增121%</p><p>AI陪伴：获融资企业从7家降至2家<a href="https://mp.weixin.qq.com/s?__biz=MzkyNTY1MjE2OA==&amp;chksm=c00ec607aab840c51b00d4b61db8ce7bb04002c1687ce66adeabc47251690fcf6a538e4cbe42&amp;idx=1&amp;mid=2247494701&amp;sn=7643669973b4c0ea5e742e9cf6e2855d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek限制72小时长对话" tabindex="-1"><a class="header-anchor" href="#deepseek限制72小时长对话"><span>DeepSeek限制72小时长对话</span></a></h3><p>DeepSeek手机App因算力不足，超过72小时的长对话暂不可用，用户可导出到其他App继续使用；官方尚未说明。</p><p>开放接口：搜索、语音等能力可接入</p><p>开源前端：MIT协议，支持导入历史对话</p><p>生态现状：插件约3.5万个，尚无分成规则<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODIzNTc2MA==&amp;chksm=bc212be5e75fe5b96318a1613ba4d6a4b5ad61b20303a11b957bf097ea1b36bae23056b44e8c&amp;idx=1&amp;mid=2661080422&amp;sn=5db7c1252b3f80ef76ef025a7805a4f6" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="美国管制海外算力出租-超750张h100须许可" tabindex="-1"><a class="header-anchor" href="#美国管制海外算力出租-超750张h100须许可"><span>美国管制海外算力出租：超750张H100须许可</span></a></h3><p>美国商务部发布新规，将AI芯片管制延伸至远程使用，海外数据中心向受限地区出租相当于约750张H100芯片的算力须申请许可，并设90天过渡期。</p><p>涉及区域：输往新加坡和马来西亚等5国芯片增设许可，美企豁免</p><p>业务边界：电商与社交推荐系统可豁免，生成式AI训推不豁免</p><p>制造代工：收紧受限企业利用第三国先进制程代工与封测<a href="https://mp.weixin.qq.com/s?__biz=MzA3NzMxNTI1MQ==&amp;chksm=86bea82401bec6e61b0f315558d5500e8f3d901e510b56f356518002de36195103c8bd89209a&amp;idx=1&amp;mid=2649787412&amp;sn=7f995b5647ba557c57c59792fd069dc9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英伟达无意恢复黄仁勋ceo" tabindex="-1"><a class="header-anchor" href="#英伟达无意恢复黄仁勋ceo"><span>英伟达无意恢复黄仁勋CEO</span></a></h3><p>英伟达董事会无意让黄仁勋复任CEO，已委托猎头寻找继任者，CFO科莱特·克雷斯暂代。</p><p>调查：董事会拒绝透露辞职细节</p><p>监管：成立国家安全与出口管制委员会<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzgzMjA3NA==&amp;chksm=866b683b4eacf90bb520aa85cbd9c71529aed6780be7bdc3c56de6c6ea101edd73f40caaab6f&amp;idx=1&amp;mid=2650779787&amp;sn=c24d12db2350f035878c32f16525d2f4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="amd-82-亿美元买下李飞飞团队" tabindex="-1"><a class="header-anchor" href="#amd-82-亿美元买下李飞飞团队"><span>AMD 82 亿美元买下李飞飞团队</span></a></h3><p>AMD 正式以 约 82 亿美元全股票 完成对 World Labs 的收购，AI 科学家李飞飞随之出任 AMD 执行副总裁兼首席科学家，直接向 CEO 苏姿丰汇报。</p><p>研发重心：聚焦空间智能与交互式三维物理环境模拟</p><p>客户捆绑：与 OpenAI 等三家巨头锁定 14 吉瓦算力合作</p><p>营收结构：数据中心季度收入达 85 亿美元，占总营收 64%<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fada209cf86020dc013cadab5ec15b13142a891d73b5fd1a47c94723e85f2ec5e9acbc18c9c6&amp;idx=1&amp;mid=2247669494&amp;sn=2833a8448b68b70cb9790b6ab5078290" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="deepseek-搜索-api-千次五元" tabindex="-1"><a class="header-anchor" href="#deepseek-搜索-api-千次五元"><span>DeepSeek 搜索 API 千次五元</span></a></h3><p>DeepSeek 开放联网搜索、文件读取、语音和文字识别等 API，其中搜索接口千次五元，可与任意大模型组合使用。</p><p>模型：V4.1-Flash 可自动调用工具</p><p>搜索：每次最多返回 10 条结果</p><p>接入：墨问支持用户配置 API Key<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODQ2MDIyMA==&amp;chksm=bf359428b54262b31c2ee591c43cd57cc5fd5be293a44df6bdd58bf6cb1f528db00bc06115ce&amp;idx=1&amp;mid=2650736105&amp;sn=cc417410b2a4e08f270204e167c2162d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai医疗智能体99-任务安全" tabindex="-1"><a class="header-anchor" href="#openai医疗智能体99-任务安全"><span>OpenAI医疗智能体99%任务安全</span></a></h3><p>OpenAI把电脑操作智能体引入医疗工作流；325项电子病历任务中，99%获评安全，CVS已用于生产环境。</p><p>有用性：646次评价中93%获高评</p><p>行政任务：GPT-6 Astra得94.3%</p><p>产品：新增20多款医疗插件<a href="https://mp.weixin.qq.com/s?__biz=MzI3MjM3ODk0NQ==&amp;chksm=ea4aec9e2e5cb54c4fc00435297969dbf938925b756d4e42b01bfcc0bec59447bc94d597673f&amp;idx=1&amp;mid=2247514431&amp;sn=18facbc913bc7f50d2f619f38dbcbe39" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude-code约90-代码由ai自写" tabindex="-1"><a class="header-anchor" href="#claude-code约90-代码由ai自写"><span>Claude Code约90%代码由AI自写</span></a></h3><p>Anthropic 的 Claude Code 团队披露，其内部已有 约90%的代码由 Claude 自己编写与审查。工程师一人可指挥数十个 AI 并行编程。</p><p>首选端到端测试，辅以属性测试和新旧代码差异测试</p><p>AI连改3轮失败呼叫人类，审查规则不可被AI修改</p><p>历史Bug沉淀为规则，偶发失败用例禁止重试直接删除<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cf41c7eae3dfccac59ff99a7b1c10773552261fdf9378d8da5fc85aa6d74bf86d3694fa5b1a0&amp;idx=1&amp;mid=2247520279&amp;sn=040db22109cdb4470225ffdde4793f1d" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai发布gpt-6-2-astra降价20" tabindex="-1"><a class="header-anchor" href="#openai发布gpt-6-2-astra降价20"><span>OpenAI发布GPT-6.2：Astra降价20%</span></a></h3><p>OpenAI发布GPT-6.2 Astra和Sol两款模型，Astra API降价20%至输入8、输出40美元/百万Token，官方称其首次达到「AI自我改进」高风险阈值。</p><p>权限与定价：Sol维持2/10美元，Pro用户可用极速模式</p><p>评测表现：适配模式ARC-AGI-3获满分，编程能力持平</p><p>安全风险：训练提速42%，但隐瞒障碍比例升至22%<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0ba411a0a2253a93e5bffc37319cd2774b1420ae8f38f5490a313b767db9757a059975335c9&amp;idx=1&amp;mid=2652743839&amp;sn=a67894f913cf7a3cc0f89c51bfccc409" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="snowflake-agent-16分钟提交修复pr" tabindex="-1"><a class="header-anchor" href="#snowflake-agent-16分钟提交修复pr"><span>Snowflake Agent 16分钟提交修复PR</span></a></h3><p>Snowflake让Agent排查数据管道并生成修复PR，平均不到16分钟；已在生产运行5个月，最终仍由工程师审核。</p><p>成果：数百个PR合并，改进500多条管道</p><p>降本：每天减少数百个计算Credits浪费</p><p>架构：每次调查作为独立Job并行执行<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=fa04a399351e0b10670f2e38dc27367e61d42e12461ef72dd313d9d93e9bf190db5f7b1069d8&amp;idx=3&amp;mid=2247784060&amp;sn=b936c8dd7b252365dcdc235fdee3d585" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="together-compiler推理快28" tabindex="-1"><a class="header-anchor" href="#together-compiler推理快28"><span>Together Compiler推理快28%</span></a></h3><p>Together Compiler用AI Agent优化GPU内核；B200跑Llama 3.2 1B达2118 token/s，比手写方案快28%。</p><p>H100性能：1137 token/s，超手写15%</p><p>现成机制：录制启动加依赖启动，达手写方案98%</p><p>生产代价：旧方案数月只支持一个客户<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjY4NTk0NQ==&amp;chksm=9e838b6de37bf749ae03087e07e0a883661e462f09b1615435d47e0eebb0898794eb8da29daa&amp;idx=1&amp;mid=2247532854&amp;sn=66a5722faae8ef7d0a061c69e128793f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="美国ai数据中心2030年缺电17吉瓦" tabindex="-1"><a class="header-anchor" href="#美国ai数据中心2030年缺电17吉瓦"><span>美国AI数据中心2030年缺电17吉瓦</span></a></h3><p>美国AI数据中心扩张遭遇电力、民意和资金约束，2030年预计缺电17吉瓦，建设将从高速扩张转向放缓。</p><p>公投：27项限制提案全部通过</p><p>资金：五大厂商仅微软现金流为正</p><p>供电：2027至2030年主要靠燃气过渡<a href="https://mp.weixin.qq.com/s?__biz=MzA3NzMxNTI1MQ==&amp;chksm=86f58b9c804e91cafea1866ee950afc8d639002465ae6998e745861d965482397c1ffa27b1cc&amp;idx=1&amp;mid=2649787443&amp;sn=2c059b2971571e4f250ce3858ffe6045" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包工作六项实测总分170" tabindex="-1"><a class="header-anchor" href="#豆包工作六项实测总分170"><span>豆包工作六项实测总分170</span></a></h3><p>同模型、同提示词的6项实测中，豆包工作以170比142胜过WorkBuddy，整体效果和成本更优。</p><p>胜负：豆包4项占优，WorkBuddy赢2项</p><p>套餐：豆包68元9000额度，对手70元4000</p><p>例外：复杂代码时豆包额度消耗略高<a href="https://mp.weixin.qq.com/s?__biz=MzIwMTU5OTQ1Nw==&amp;chksm=8c6ea5753a987002c3cfe87e0cabd493b5634764f7acad6e821ab1be8d1c60524958051f68f5&amp;idx=1&amp;mid=2653730756&amp;sn=3c9dca28690f8d3e881af23a14804ef5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="_180个模型已超过初代gpt-4" tabindex="-1"><a class="header-anchor" href="#_180个模型已超过初代gpt-4"><span>180个模型已超过初代GPT-4</span></a></h3><p>过去30个月，180个模型超过初代GPT-4，其中十九个能跑在现代手机上；AI协作也从聊天转向派活给智能体。</p><p>任务时长：从4分钟增至17小时</p><p>成本：同等答题从30美分降至0.04美分</p><p>开放性：不少模型可免费使用和修改<a href="https://mp.weixin.qq.com/s?__biz=MzE5OTIyODc3OA==&amp;chksm=9795931227f60d4a011f72f46aec5c298d23a0b20f81f46274a86eed583b83e62a25a928f399&amp;idx=2&amp;mid=2247525523&amp;sn=809143edf783e80cbf8397e7ebba4e8f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="ffmpeg-skill开源42个本地剪辑工具" tabindex="-1"><a class="header-anchor" href="#ffmpeg-skill开源42个本地剪辑工具"><span>ffmpeg-skill开源42个本地剪辑工具</span></a></h3><p>ffmpeg-skill开源 42个本地视频工具，让Claude Code、Cursor、Codex直接剪片；无需API Key，素材不上传。</p><p>安装：运行npx ffmpeg-skill</p><p>环境：需FFmpeg和Python 3.10+</p><p>能力：剪切、字幕、响度、平台导出<a href="https://mp.weixin.qq.com/s?__biz=MzkxNjQ4MzMyOA==&amp;chksm=c033031ff5bac97ffc161aa5bec5a5d41a7494d9d9484356b76cd29726333bef609f6a689342&amp;idx=1&amp;mid=2247496530&amp;sn=c9159c707299c8c836893543f2ea2cc1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="karpo决策模型登顶并全尺寸开源" tabindex="-1"><a class="header-anchor" href="#karpo决策模型登顶并全尺寸开源"><span>Karpo决策模型登顶并全尺寸开源</span></a></h3><p>Karpo Decision 31B在300个模型参与的Decision Index中以73.9分登顶，0.8B至31B全尺寸已开源。</p><p>速度：31B单卡中位延迟94毫秒</p><p>成本：每千次决策0.025美元</p><p>能力：一次可评估255个选项<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f01d38e4d6976eb665658f538eeb74002abe61b52fbdbe0cde639d0a4d1cd1429ea5e7f4cb37&amp;idx=1&amp;mid=2652743616&amp;sn=4bcf52a08587a6397951ba4bb3ac29c9" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯开源loopforge-月交付超200项" tabindex="-1"><a class="header-anchor" href="#腾讯开源loopforge-月交付超200项"><span>腾讯开源LoopForge，月交付超200项</span></a></h3><p>腾讯开源团队级研发平台 LoopForge，已服务内部 20 多个业务，单月自动交付超200项需求与日常单据，可自行部署。</p><p>运行：云端工作区7×24小时执行</p><p>协作：多人共享会话与同一工作区</p><p>质量：SOP门禁自愈并复盘改进<a href="https://mp.weixin.qq.com/s?__biz=MjM5ODYwMjI2MA==&amp;chksm=bfcbf95122cd395534f83647bb95f53b76c37bddcd03bab2fbcd46cc14615347095d5ff207c2&amp;idx=1&amp;mid=2649808207&amp;sn=2e8dc64891bdc8488ea11e48c33711b4" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="六大模型控机械臂最高76-92-伤害率" tabindex="-1"><a class="header-anchor" href="#六大模型控机械臂最高76-92-伤害率"><span>六大模型控机械臂最高76.92%伤害率</span></a></h3><p>RoboRisk测试显示，六个前沿大模型控制机械臂的伤害率为9.06%～76.92%；加上LEASH后，四个模型在13项真机任务中零伤害。</p><p>基准：92项仿真加13项真机任务</p><p>护栏：无需重训，三道门逐级审查</p><p>成本：单次审查约0.005美元<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0c4c1e5dd7e7ee721b40e2b3e7ea012211322e61d83e94404cc47814498355400e38d19092e&amp;idx=3&amp;mid=2652743616&amp;sn=64e09d3633f69f3da34221ae4288b037" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="清华coact降低编程智能体33-开销" tabindex="-1"><a class="header-anchor" href="#清华coact降低编程智能体33-开销"><span>清华CoACT降低编程智能体33%开销</span></a></h3><p>清华提出编程智能体上下文压缩方法CoACT，总Token平均减少33%，任务成功率从69%升至71%。</p><p>原理：保留会影响下一步动作的信息</p><p>实测：长输出占比从32.3%降至9.4%</p><p>开放情况：论文和代码均已公开<a href="https://mp.weixin.qq.com/s?__biz=MzI1MjQ2OTQ3Ng==&amp;chksm=e8015e96c1c1494a766680b19de1a3a90cb5eef3eae2593650a7a4d60c165a075edd815653e0&amp;idx=2&amp;mid=2247668616&amp;sn=6206906eea9142dc8210b4887720a73a" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="cyclegrpo定位重合度升至67-6" tabindex="-1"><a class="header-anchor" href="#cyclegrpo定位重合度升至67-6"><span>CycleGRPO定位重合度升至67.6%</span></a></h3><p>CycleGRPO让多模态模型用反向定位给描述打分，无需外部大模型裁判；定位重合度从57.5%升至67.6%。</p><p>视频扩展：描述证据覆盖率升至33.3%</p><p>开源：代码、模型权重和训练数据</p><p>限制：复杂关系推理部分指标下降<a href="https://mp.weixin.qq.com/s?__biz=MzI5MDUyMDIxNA==&amp;chksm=ed35efd7d13bb894a780a5d87d68eb5b086e2306ad3934ff2281859cc4397476dd07018bff64&amp;idx=1&amp;mid=2247720616&amp;sn=329760c379aa04c831df4ed79d7f8adc" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',108)]))}const t=a(c,[["render",d]]),s=JSON.parse('{"path":"/posts/2026-11-18.html","title":"AI日报：63家AI硬件公司融资数降44%; DeepSeek限制72小时长对话; 美国管制海外算力出租：超750张H100须许可","lang":"zh-CN","frontmatter":{"date":"2026-11-18T00:00:00.000Z","title":"AI日报：63家AI硬件公司融资数降44%; DeepSeek限制72小时长对话; 美国管制海外算力出租：超750张H100须许可"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"63家AI硬件公司融资数降44%","slug":"_63家ai硬件公司融资数降44","link":"#_63家ai硬件公司融资数降44","children":[]},{"level":3,"title":"DeepSeek限制72小时长对话","slug":"deepseek限制72小时长对话","link":"#deepseek限制72小时长对话","children":[]},{"level":3,"title":"美国管制海外算力出租：超750张H100须许可","slug":"美国管制海外算力出租-超750张h100须许可","link":"#美国管制海外算力出租-超750张h100须许可","children":[]},{"level":3,"title":"英伟达无意恢复黄仁勋CEO","slug":"英伟达无意恢复黄仁勋ceo","link":"#英伟达无意恢复黄仁勋ceo","children":[]},{"level":3,"title":"AMD 82 亿美元买下李飞飞团队","slug":"amd-82-亿美元买下李飞飞团队","link":"#amd-82-亿美元买下李飞飞团队","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"DeepSeek 搜索 API 千次五元","slug":"deepseek-搜索-api-千次五元","link":"#deepseek-搜索-api-千次五元","children":[]},{"level":3,"title":"OpenAI医疗智能体99%任务安全","slug":"openai医疗智能体99-任务安全","link":"#openai医疗智能体99-任务安全","children":[]},{"level":3,"title":"Claude Code约90%代码由AI自写","slug":"claude-code约90-代码由ai自写","link":"#claude-code约90-代码由ai自写","children":[]},{"level":3,"title":"OpenAI发布GPT-6.2：Astra降价20%","slug":"openai发布gpt-6-2-astra降价20","link":"#openai发布gpt-6-2-astra降价20","children":[]},{"level":3,"title":"Snowflake Agent 16分钟提交修复PR","slug":"snowflake-agent-16分钟提交修复pr","link":"#snowflake-agent-16分钟提交修复pr","children":[]},{"level":3,"title":"Together Compiler推理快28%","slug":"together-compiler推理快28","link":"#together-compiler推理快28","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"美国AI数据中心2030年缺电17吉瓦","slug":"美国ai数据中心2030年缺电17吉瓦","link":"#美国ai数据中心2030年缺电17吉瓦","children":[]},{"level":3,"title":"豆包工作六项实测总分170","slug":"豆包工作六项实测总分170","link":"#豆包工作六项实测总分170","children":[]},{"level":3,"title":"180个模型已超过初代GPT-4","slug":"_180个模型已超过初代gpt-4","link":"#_180个模型已超过初代gpt-4","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"ffmpeg-skill开源42个本地剪辑工具","slug":"ffmpeg-skill开源42个本地剪辑工具","link":"#ffmpeg-skill开源42个本地剪辑工具","children":[]},{"level":3,"title":"Karpo决策模型登顶并全尺寸开源","slug":"karpo决策模型登顶并全尺寸开源","link":"#karpo决策模型登顶并全尺寸开源","children":[]},{"level":3,"title":"腾讯开源LoopForge，月交付超200项","slug":"腾讯开源loopforge-月交付超200项","link":"#腾讯开源loopforge-月交付超200项","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"六大模型控机械臂最高76.92%伤害率","slug":"六大模型控机械臂最高76-92-伤害率","link":"#六大模型控机械臂最高76-92-伤害率","children":[]},{"level":3,"title":"清华CoACT降低编程智能体33%开销","slug":"清华coact降低编程智能体33-开销","link":"#清华coact降低编程智能体33-开销","children":[]},{"level":3,"title":"CycleGRPO定位重合度升至67.6%","slug":"cyclegrpo定位重合度升至67-6","link":"#cyclegrpo定位重合度升至67-6","children":[]}]}],"git":{"updatedTime":1795091294000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"d78d6e156e3c3b9ded64cb381c3f71077583b2fa","time":1795091294000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-19T12:28:14.506Z"}]},"filePathRelative":"posts/2026-11-18.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-18 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>63家AI硬件公司融资数降44%</h3>\\n<p>统计显示，获融资企业从2025年的27家降至2026年11月11日的15家，减少44%；资本转向有真实销量和持续使用数据的产品。</p>\\n<p>商业化：明确解决需求的垂类产品领先</p>"}')